#!/bin/zsh
# Remove what setup.sh installed, restore what it moved aside, and sign out of GitHub.
set -euo pipefail

GIT_DIR="$HOME/.dotfiles"
BACKUP_DIR="$HOME/.dotfiles-preexisting"
INSTALLED_LIST="$GIT_DIR/installed-files"
RULES_LINK_DIR="$HOME/.claude/rules"

if [[ ! -f "$INSTALLED_LIST" ]]; then
  echo "No setup.sh install found at $GIT_DIR, nothing to remove." >&2
  exit 0
fi

# Rule links generated by sync-cursor-rules.sh point into ~/.cursor/rules.
for link in "$RULES_LINK_DIR"/*.md(N@); do
  [[ "$(readlink "$link")" == "$HOME/.cursor/rules/"* ]] && rm "$link"
done

while read -r file; do
  rm -f "$HOME/$file"
done < "$INSTALLED_LIST"

if [[ -d "$BACKUP_DIR" ]]; then
  (cd "$BACKUP_DIR" && find . \( -type f -o -type l \) -print) | while read -r file; do
    mkdir -p "$HOME/${file:h}"
    mv "$BACKUP_DIR/$file" "$HOME/$file"
  done
  rm -rf "$BACKUP_DIR"
fi

rm -rf "$GIT_DIR"
rmdir "$HOME/.dotfiles-bin" "$HOME/.github" 2>/dev/null || true

if gh auth status -h github.com >/dev/null 2>&1; then
  gh auth logout -h github.com
fi
echo "Removed. Sign out of Claude Code (/logout) and Cursor (Settings, Sign Out) yourself."
